import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { getJob, listJobs, submitJob, workerIsUp } from './jobs.ts';
import { parseSubmission, type FieldError } from './validation.ts';

/** Largest request body accepted. A valid submission is far smaller (input is at most 1000 characters). */
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

/** Reads the whole body, or resolves null when it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        resolve(null);
        req.resume();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(size > MAX_BODY_BYTES ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method === 'HEAD' ? 'GET' : (req.method ?? '');
  const jobMatch = /^\/api\/jobs\/([^/]+)$/.exec(pathname);

  let allowed: string[] | undefined;
  if (pathname === '/' || pathname === '/health' || jobMatch) allowed = ['GET'];
  else if (pathname === '/api/jobs') allowed = ['GET', 'POST'];
  if (!allowed) return sendError(res, 404, 'not_found', `No route for ${pathname}.`);
  if (!allowed.includes(method)) {
    res.setHeader('allow', allowed.join(', '));
    return sendError(res, 405, 'method_not_allowed', `${req.method} is not allowed for ${pathname}.`);
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    return send(res, 200, { status: 'ok', worker: workerIsUp(db) ? 'up' : 'down' });
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobs(db) });

    const body = await readBody(req);
    if (body === null) res.setHeader('connection', 'close');
    const parsed = parseSubmission({
      contentType: req.headers['content-type'],
      body,
      idempotencyKey: req.headers['idempotency-key'],
    });
    if (!parsed.ok) return sendError(res, 400, 'invalid_request', 'The request is invalid.', parsed.fields);

    const outcome = submitJob(db, parsed.job, parsed.idempotencyKey);
    if (outcome.kind === 'conflict') {
      return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
    return send(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
  }

  // GET /api/jobs/:id
  let id: string;
  try {
    id = decodeURIComponent(jobMatch![1]!);
  } catch {
    return sendError(res, 404, 'not_found', 'No such job.');
  }
  const job = getJob(db, id);
  if (!job) return sendError(res, 404, 'not_found', 'No such job.');
  return send(res, 200, job);
}

const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (stopping) return;
    stopping = true;
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeAllConnections();
  });
}

