1	import { randomUUID } from 'node:crypto';
2	import type { DatabaseSync } from 'node:sqlite';
3	
4	export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
5	
6	export interface Job {
7	  id: string;
8	  status: JobStatus;
9	  input: string;
10	  steps: number;
11	  failAttempts: number;
12	  attempts: number;
13	  progress: { completed: number; total: number };
14	  result: { output: string } | null;
15	  error: string | null;
16	  createdAt: string;
17	  updatedAt: string;
18	}
19	
20	export interface NewJob {
21	  input: string;
22	  steps: number;
23	  failAttempts: number;
24	}
25	
26	/** Maximum number of processing attempts per job, including the first. */
27	export const MAX_ATTEMPTS = 3;
28	export const TRANSIENT_FAILURE = 'transient failure';
29	export const WORKER_HEARTBEAT = 'worker';
30	/** The worker writes a heartbeat about once a second; it counts as down after this long without one. */
31	export const HEARTBEAT_TIMEOUT_MS = 3000;
32	
33	interface JobRow {
34	  seq: number;
35	  id: string;
36	  status: JobStatus;
37	  input: string;
38	  steps: number;
39	  fail_attempts: number;
40	  attempts: number;
41	  completed: number;
42	  result_output: string | null;
43	  error: string | null;
44	  created_at: string;
45	  updated_at: string;
46	}
47	
48	const JOB_COLUMNS = 'seq, id, status, input, steps, fail_attempts, attempts, completed, result_output, error, created_at, updated_at';
49	
50	function toJob(r: JobRow): Job {
51	  return {
52	    id: r.id,
53	    status: r.status,
54	    input: r.input,
55	    steps: r.steps,
56	    failAttempts: r.fail_attempts,
57	    attempts: r.attempts,
58	    progress: { completed: r.completed, total: r.steps },
59	    result: r.status === 'completed' ? { output: r.result_output ?? '' } : null,
60	    error: r.status === 'failed' ? r.error : null,
61	    createdAt: r.created_at,
62	    updatedAt: r.updated_at,
63	  };
64	}
65	
66	type Param = string | number | null;
67	
68	function one(db: DatabaseSync, sql: string, ...params: Param[]): JobRow | undefined {
69	  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
70	}
71	
72	/** Runs `fn` inside an immediate write transaction, so concurrent writers wait instead of interleaving. */
73	export function transaction<T>(db: DatabaseSync, fn: () => T): T {
74	  db.exec('BEGIN IMMEDIATE');
75	  try {
76	    const result = fn();
77	    db.exec('COMMIT');
78	    return result;
79	  } catch (e) {
80	    try {
81	      db.exec('ROLLBACK');
82	    } catch {
83	      // the transaction was already closed
84	    }
85	    throw e;
86	  }
87	}
88	
89	export type SubmitOutcome = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };
90	
91	/**
92	 * Creates a job, or handles an idempotent replay. The key check and the insert share one
93	 * transaction, and the key is unique in the database, so a key never creates two jobs.
94	 */
95	export function submitJob(db: DatabaseSync, job: NewJob, idempotencyKey: string | undefined): SubmitOutcome {
96	  return transaction(db, (): SubmitOutcome => {
97	    if (idempotencyKey !== undefined) {
98	      const existing = one(db, `SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`, idempotencyKey);
99	      if (existing) {
100	        const same = existing.input === job.input && existing.steps === job.steps && existing.fail_attempts === job.failAttempts;
101	        return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
102	      }
103	    }
104	    const now = new Date().toISOString();
105	    const id = randomUUID();
106	    db.prepare(
107	      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, run_after, idempotency_key, created_at, updated_at)
108	       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)`,
109	    ).run(id, job.input, job.steps, job.failAttempts, Date.now(), idempotencyKey ?? null, now, now);
110	    return { kind: 'created', job: toJob(one(db, `SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`, id)!) };
111	  });
112	}
113	
114	export function getJob(db: DatabaseSync, id: string): Job | undefined {
115	  const row = one(db, `SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`, id);
116	  return row ? toJob(row) : undefined;
117	}
118	
119	export function listJobs(db: DatabaseSync): Job[] {
120	  return (db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[]).map(toJob);
121	}
122	
123	/** Moves the oldest queued job that is ready to run into `running` and counts the new attempt. */
124	export function claimNextJob(db: DatabaseSync): Job | undefined {
125	  return transaction(db, () => {
126	    const next = one(db, `SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`, Date.now());
127	    if (!next) return undefined;
128	    db.prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?`).run(
129	      new Date().toISOString(),
130	      next.seq,
131	    );
132	    return toJob(one(db, `SELECT ${JOB_COLUMNS} FROM jobs WHERE seq = ?`, next.seq)!);
133	  });
134	}
135	
